def _collatz_iter(n: int, k: int) -> int:
    """Apply the Collatz map to n exactly k times and return the result."""
    for _ in range(k):
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
    return n

def collatz_steps(n: int) -> int:
    """pre: n >= 1
post: __return__ >= 0
post: _collatz_iter(n, __return__) == 1
post: all(_collatz_iter(n, j) != 1 for j in range(__return__))"""
    steps = 0
    current = n
    while current != 1:
        if current % 2 == 0:
            current = current // 2
        else:
            current = 3 * current + 1
        steps += 1
    return steps

